"use client";

import {
  BriefcaseIcon,
  PlusCircleIcon,
  ArrowPathIcon,
  CommandLineIcon,
} from "@heroicons/react/20/solid";

interface QuickActionProps {
  label: string;
  icon: React.ReactNode;
  onClick?: () => void;
}

function QuickActionPill({ label, icon, onClick }: QuickActionProps) {
  return (
    <button
      onClick={onClick}
      className="inline-flex items-center gap-1.5 rounded-full border border-border bg-surface px-3.5 py-1.5 text-xs font-medium text-text-secondary transition-all hover:border-primary/30 hover:text-text-primary hover:bg-surface-elevated cursor-pointer"
    >
      {icon}
      {label}
    </button>
  );
}

interface QuickActionsProps {
  onNavigateJobs?: () => void;
}

export function QuickActions({ onNavigateJobs }: QuickActionsProps) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <QuickActionPill
        label="Jobs"
        icon={<BriefcaseIcon className="h-3.5 w-3.5" />}
        onClick={onNavigateJobs}
      />
      <QuickActionPill
        label="Create Job"
        icon={<PlusCircleIcon className="h-3.5 w-3.5" />}
      />
      <QuickActionPill
        label="Restart"
        icon={<ArrowPathIcon className="h-3.5 w-3.5" />}
      />
      <QuickActionPill
        label="System Logs"
        icon={<CommandLineIcon className="h-3.5 w-3.5" />}
      />
    </div>
  );
}
