"use client";

import type { Run } from "@/lib/mock-data";

interface CostChartProps {
  runs: Run[];
}

export function CostChart({ runs }: CostChartProps) {
  // Extract cost numbers from runs that have cost data
  const costData = runs
    .filter((r) => r.cost && r.cost !== "--")
    .slice(0, 8)
    .reverse()
    .map((r) => ({
      label: r.id.length > 8 ? r.id.slice(0, 8) : r.id,
      cost: parseFloat(r.cost.replace("$", "")) || 0,
    }));

  if (costData.length === 0) {
    return (
      <div className="flex items-center justify-center h-full text-xs text-text-secondary/50">
        No cost data
      </div>
    );
  }

  const max = Math.max(...costData.map((d) => d.cost), 0.01);

  return (
    <div className="flex items-end gap-1.5 h-full px-1">
      {costData.map((d, i) => (
        <div
          key={i}
          className="flex flex-1 flex-col items-center gap-1 min-w-0"
        >
          <span className="text-[9px] text-text-secondary/50 font-mono truncate w-full text-center">
            ${d.cost.toFixed(2)}
          </span>
          <div className="w-full relative flex-1 flex items-end">
            <div
              className="w-full rounded-t-sm transition-all duration-300"
              style={{
                height: `${Math.max((d.cost / max) * 100, 4)}%`,
                background:
                  d.cost === max
                    ? "oklch(0.70 0.15 55)"
                    : "oklch(0.70 0.15 55 / 0.35)",
              }}
            />
          </div>
        </div>
      ))}
    </div>
  );
}
